// ============================================
// KONFIGURASI SUMBER SCRAPING
// Tambahkan portal loker di sini
// ============================================

const sources = [
  {
    name: 'glints',
    scrape_url: 'https://glints.com/id/opportunities/jobs/explore',
    base_url: 'https://glints.com'
  }
  // Tambahkan sumber lain:
  // { name: 'jobstreet', scrape_url: 'https://www.jobstreet.co.id/...', base_url: 'https://www.jobstreet.co.id' },
  // { name: 'kalibrr', scrape_url: 'https://www.kalibrr.com/...', base_url: 'https://www.kalibrr.com' },
];

return sources.map(s => ({ json: s }));

// ============================================
// POTONG HTML MENJADI CHUNKS YANG BISA DIPROSES AI
// Model gratis punya limit context ~4-8K tokens
// ============================================

const html = $input.first().json.data;
const sourceConfig = $('Daftar Sumber').first().json;

// Bersihkan HTML: hapus script, style, nav, footer, header
let cleaned = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<footer[\s\S]*?<\/footer>/gi, '')
  .replace(/<header[\s\S]*?<\/header>/gi, '')
  .replace(/<svg[\s\S]*?<\/svg>/gi, '')
  .replace(/<img[^>]*>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Potong per ~3000 karakter (aman untuk context window model gratis)
const CHUNK_SIZE = 3000;
const chunks = [];

for (let i = 0; i < cleaned.length; i += CHUNK_SIZE) {
  const chunk = cleaned.substring(i, i + CHUNK_SIZE);
  // Hanya kirim chunk yang kemungkinan mengandung data loker
  if (chunk.includes('job') || chunk.includes('loker') || chunk.includes('lowongan') || 
      chunk.includes('vacancy') || chunk.includes('career') || chunk.includes('opportunity') ||
      chunk.includes('gizi') || chunk.includes('developer') || chunk.includes('manager') ||
      chunk.includes('Rp') || chunk.includes('Full') || chunk.includes('Part')) {
    chunks.push({
      html_chunk: chunk,
      source_name: sourceConfig.name,
      base_url: sourceConfig.base_url,
      chunk_index: chunks.length,
    });
  }
}

// Batasi maksimal 10 chunks untuk hemat token
const limited = chunks.slice(0, 10);

if (limited.length === 0) {
  throw new Error(`Tidak ada konten loker ditemukan dari ${sourceConfig.name}`);
}

return limited.map(c => ({ json: c }));

// ============================================
// PARSE AI EXTRACTION RESPONSE
// Gabungkan semua chunk results + deduplicate
// ============================================

const items = $input.all();
const sourceConfig = $('Daftar Sumber').first().json;
const baseUrl = sourceConfig.base_url || '';
const seen = new Set();
const jobs = [];

for (const item of items) {
  try {
    const content = item.json.choices?.[0]?.message?.content || '';
    let parsed = null;

    // Coba parse JSON array
    try {
      parsed = JSON.parse(content);
    } catch (e) {
      // Extract JSON array dari text
      const match = content.match(/\[[\s\S]*\]/);
      if (match) {
        try { parsed = JSON.parse(match[0]); } catch (e2) {}
      }
    }

    if (!Array.isArray(parsed)) continue;

    for (const job of parsed) {
      if (!job.title || !job.source_path) continue;

      // Buat URL lengkap
      const sourceUrl = job.source_path.startsWith('http')
        ? job.source_path
        : baseUrl + job.source_path;

      // Deduplicate by source_url
      if (seen.has(sourceUrl)) continue;
      seen.add(sourceUrl);

      // Parse salary text ke angka
      let salaryMin = null;
      let salaryMax = null;
      if (job.salary_text) {
        const salaryNums = job.salary_text.match(/([\d.,]+)/g);
        if (salaryNums && salaryNums.length >= 1) {
          const parseNum = (s) => {
            let n = parseFloat(s.replace(/\./g, '').replace(',', '.'));
            // Jika ada 'jt' atau 'juta', kalikan 1.000.000
            if (job.salary_text.toLowerCase().includes('jt') || job.salary_text.toLowerCase().includes('juta')) {
              n = n * 1000000;
            }
            return Math.round(n);
          };
          salaryMin = parseNum(salaryNums[0]);
          if (salaryNums.length >= 2) {
            salaryMax = parseNum(salaryNums[1]);
          }
        }
      }

      jobs.push({
        title: job.title.trim(),
        company: (job.company || 'Tidak diketahui').trim(),
        location: job.location || null,
        source_url: sourceUrl,
        employment_type: job.employment_type || null,
        salary_min: salaryMin,
        salary_max: salaryMax,
        tags: Array.isArray(job.tags) ? job.tags : [],
        description_raw: null,
        source_name: sourceConfig.name,
      });
    }
  } catch (e) {
    // Skip chunk yang gagal parse
  }
}

if (jobs.length === 0) {
  throw new Error(`AI tidak menemukan lowongan dari ${sourceConfig.name}. Cek apakah HTML ter-scrape dengan benar.`);
}

return jobs.map(j => ({ json: j }));

