// Gabungkan enrichment result dengan data loker asli

const items = $input.all();
const batchItems = $('Batch per 5').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const ai = items[i].json;
  const original = batchItems[i]?.json || {};
  let summary = '';
  let enrichedTags = original.tags || [];

  try {
    const content = ai.choices?.[0]?.message?.content || '';
    let parsed = null;
    try { parsed = JSON.parse(content); } catch (e) {
      const m = content.match(/\{[\s\S]*\}/);
      if (m) try { parsed = JSON.parse(m[0]); } catch (e2) {}
    }
    if (parsed) {
      summary = parsed.summary || '';
      if (Array.isArray(parsed.tags)) {
        // Merge tags dari extraction + enrichment, deduplicate
        const allTags = [...new Set([...enrichedTags, ...parsed.tags])];
        enrichedTags = allTags.slice(0, 6);
      }
    }
  } catch (e) {}

  results.push({ json: {
    ...original,
    summary_ai: summary,
    tags: enrichedTags,
  }});
}

return results;

// Bangun payload untuk Laravel API

const items = $input.all();
const sourceName = items[0]?.json?.source_name || 'unknown';

return [{ json: {
  source: sourceName,
  scraped_at: new Date().toISOString(),
  jobs: items.map(item => ({
    title: item.json.title,
    company: item.json.company,
    location: item.json.location,
    employment_type: item.json.employment_type,
    salary_min: item.json.salary_min,
    salary_max: item.json.salary_max,
    description_raw: item.json.description_raw,
    summary_ai: item.json.summary_ai,
    tags: item.json.tags,
    source_url: item.json.source_url,
  }))
}}];

const r = $input.first().json;
return [{ json: {
  status: 'OK',
  source: r.source,
  inserted: r.stats?.inserted || 0,
  updated: r.stats?.updated || 0,
  errors: r.stats?.errors?.length || 0,
  timestamp: new Date().toISOString(),
}}];
